#!/usr/bin/env bash
set -euo pipefail

# Compatibility wrapper.
#
# Systemd units are generated by RUN_AFTER_UPLOAD.sh now.  Keeping a second
# unit source under ops/ was brittle: it drifted from the staged worker layout
# and expected a removed $PROJECT_DIR/systemd directory.  Delegate to the
# canonical server-control script so every install path writes the same units.

PROJECT_DIR="${PROJECT_DIR:-/root/arachne}"
CONTROL_SCRIPT="$PROJECT_DIR/RUN_AFTER_UPLOAD.sh"

if [[ ! -f "$CONTROL_SCRIPT" ]]; then
  echo "RUN_AFTER_UPLOAD.sh not found at: $CONTROL_SCRIPT" >&2
  echo "Set PROJECT_DIR to the Arachne project directory and rerun." >&2
  exit 1
fi

exec bash "$CONTROL_SCRIPT" install
